param([string]$GameRoot='F:/SteamLibrary/steamapps/common/RimWorld')
# Read-only, selected gameplay projections; full derived C# remains local.
$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$out=Join-Path $root 'docs/research/rimworld/evidence'
function Source([string]$file,[int]$start=1,[int]$end=0){
 $p=Join-Path $root $file;$lines=Get-Content -LiteralPath $p
 if(!$end){$end=$lines.Count};if($start -lt 1 -or $end -gt $lines.Count -or $end -lt $start){throw "Invalid range $file"}
 [ordered]@{file=$file;sha256=(Get-FileHash -LiteralPath $p).Hash.ToLowerInvariant();lines=@($start,$end)}
}
$claims=@(
 [ordered]@{id='FQ01';finding='Only furniture with inherited CompQuality gets a quality roll. Bed, DiningChair and Table1x2c have the component; HorseshoesPin has none. TryGetQuality returns false with Normal output for no component; StatRequest uses this computational fallback without adding a quality component.';sources=@((Source '.local-research/weapons/RimWorld.QualityUtility.cs'),(Source '.local-research/furniture-quality/RimWorld.StatRequest.cs' 54 98));xml=@('FQX01','FQX02','FQX03')},
 [ordered]@{id='FQ02';finding='Ordinary FinishFrame reserves an accessible player frame with materials and valid skills. Work increments ConstructionSpeed*1.7*delta, with Stuff ConstructionSpeedFactor; Construction XP .25*delta when resources and skills exist. Failure check is independent of quality: 1-pow(ConstructSuccessChance, workIncrement/workRequired).';sources=@((Source '.local-research/skills/RimWorld.JobDriver_ConstructFinishFrame.cs'),(Source '.local-research/anatomy/RimWorld.WorkGiver_ConstructFinishFrames.cs'));xml=@()},
 [ordered]@{id='FQ03';finding='On workDone>=WorkToBuild, CompleteConstruction(actor) creates the finished thing and sets quality once using that finishing actor current Construction skill. It destroys frame resources, handles art, inherits ceil(frameHP/frameMaxHP*finishedMaxHP), spawns the result and increments ThingsConstructed. It is not the planner or mean contributor skill.';sources=@((Source '.local-research/storyteller/RimWorld.Frame.cs' 262 375),(Source '.local-research/skills/RimWorld.JobDriver_ConstructFinishFrame.cs' 39 80));xml=@()},
 [ordered]@{id='FQ04';finding='Quality uses skill-level centers, asymmetric Gaussian .6/.8, integer truncation and clamp0..5; a rolled Masterwork has50% reroll using .6/.95. Inspired_Creativity adds2 capped6; pawn overload can consume inspiration. Mech skill and ideology production-role offset are separate branches. No exact probability table is inferred.';sources=@((Source '.local-research/weapons/RimWorld.QualityUtility.cs' 160 267));xml=@()},
 [ordered]@{id='FQ05';finding='CompQuality runtime field starts Normal but serialized missing quality defaults Awful. Existing saved quality persists; SetQuality also handles art and post-quality callbacks. Missing quality on a thing without CompQuality means no quality, not Awful.';sources=@((Source '.local-research/armor/RimWorld.CompQuality.cs'));xml=@('FQX02','FQX03')},
 [ordered]@{id='FQ06';finding='CompArt records authorName only when CanShowArt is true. Bed and DiningChair inherit minimum artistic quality Excellent. Poor beds therefore need not retain creator name or pawn ID. Finished-actor attribution can use before-job and after-construction evidence; a web craftedBy field would be additional provenance.';sources=@((Source '.local-research/furniture-quality/RimWorld.CompArt.cs' 48 61),(Source '.local-research/furniture-quality/RimWorld.CompArt.cs' 124 154),(Source '.local-research/storyteller/RimWorld.Frame.cs' 291 308));xml=@('FQX02')},
 [ordered]@{id='FQ07';finding='MaxHitPoints has no Quality part. Wood factor .65 yields Bed91, DiningChair65, Table1x2c49 and HorseshoesPin49 after integer rounding. Frame health is separate and finished health preserves its fraction with ceiling.';sources=@((Source '.local-research/housing/RimWorld.StatWorker.cs' 800 835),(Source '.local-research/storyteller/RimWorld.Frame.cs' 314 324));xml=@('FQX01','FQX02','FQX03','FQX04','FQX05')},
 [ordered]@{id='FQ08';finding='Comfort factors Awful..Legendary .76,.88,1,1.12,1.24,1.45,1.7 multiply bed .75 or chair .70. Table/pin define no comfort. Stat quality transforms only positive inputs by default, with min(multiplier gain,maxGain). Furniture comfort above1 is distinct from a need-level cap.';sources=@((Source '.local-research/housing/RimWorld.StatPart_Quality.cs'));xml=@('FQX02','FQX04')},
 [ordered]@{id='FQ09';finding='BedRestEffectiveness factors .86,.92,1,1.08,1.14,1.25,1.6 multiply bed base1. Stat min .4; valueIfMissing .8 is not the bed base. These are rest gain multipliers, not directly hours saved.';sources=@((Source '.local-research/housing/RimWorld.StatPart_Quality.cs'));xml=@('FQX02','FQX06')},
 [ordered]@{id='FQ10';finding='Beauty base bed1,chair8,table.5,pin missing=>0. Factors -.1,.5,1,2,3,5,8 apply to positive base values; final Mathf.RoundToInt means .5 rounds to even0. Quality does not make an undefined zero beautiful.';sources=@((Source '.local-research/housing/RimWorld.StatPart_Quality.cs'),(Source '.local-research/housing/RimWorld.StatWorker.cs' 800 835));xml=@('FQX02','FQX03','FQX04','FQX05')},
 [ordered]@{id='FQ11';finding='Stuff-built furniture base market value is material amount*stuff market value/VolumePerUnit plus .0036*max(WorkToBuild,WorkToMake) when work>2, divided by productCount. Wood WorkToBuild factor.7 gives bed560; value=54+2.016=56.016 before quality. UI formatted money is not full precision.';sources=@((Source '.local-research/storyteller/RimWorld.StatWorker_MarketValue.cs' 54 96));xml=@('FQX02','FQX05','FQX07','FQX08')},
 [ordered]@{id='FQ12';finding='Market quality factors .5,.75,1,1.25,1.5,2.5,5; positive gain caps Good500,Excellent1000,Masterwork2000,Legendary3000. MarketValue additionally uses health curve(0,0),(.5,.1),(.6,.5),(.9,1), but MarketValueIgnoreHp does not. Final values over200 round to a multiple of5.';sources=@((Source '.local-research/housing/RimWorld.StatPart_Quality.cs'),(Source '.local-research/housing/RimWorld.StatWorker.cs' 800 835));xml=@('FQX04')},
 [ordered]@{id='FQ13';finding='WealthWatcher colony building wealth uses MarketValueIgnoreHp; RoomStatWorker_Wealth uses ordinary thing.MarketValue. Both can reflect quality, but only the latter reflects current damage. A new quality roll can affect storyteller wealth without a general damage discount to building wealth.';sources=@((Source '.local-research/economy/RimWorld.WealthWatcher.cs'),(Source '.local-research/environment/RimWorld.RoomStatWorker_Wealth.cs'));xml=@('FQX04')}
)
$specs=@(
 @('FQX01','Data/Core/Defs/ThingDefs_Buildings/Buildings_Base.xml','/Defs/ThingDef[@Name="BuildingBase"]'),
 @('FQX02','Data/Core/Defs/ThingDefs_Buildings/Buildings_Furniture.xml','/Defs/ThingDef[@Name="FurnitureBase" or @Name="FurnitureWithQualityBase" or @Name="ArtableFurnitureBase" or @Name="TableBase" or @Name="TableGatherSpotBase" or @Name="BedBase" or @Name="BedWithQualityBase" or @Name="ArtableBedBase" or @Name="SansComfortBedBase" or @Name="BasicBedBase" or defName="Bed" or defName="DiningChair" or defName="Table1x2c"]'),
 @('FQX03','Data/Core/Defs/ThingDefs_Buildings/Buildings_Joy.xml','/Defs/ThingDef[defName="HorseshoesPin"]'),
 @('FQX04','Data/Core/Defs/Stats/Stats_Basics_General.xml','/Defs/StatDef[defName="MaxHitPoints" or @Name="MarketValueBase" or defName="MarketValue" or defName="MarketValueIgnoreHp" or defName="Beauty" or defName="Comfort"]'),
 @('FQX05','Data/Core/Defs/ThingDefs_Items/Items_Resource_Stuff.xml','/Defs/ThingDef[defName="WoodLog"]'),
 @('FQX06','Data/Core/Defs/Stats/Stats_Building_Special.xml','/Defs/StatDef[defName="BedRestEffectiveness" or defName="WorkToBuild"]'),
 @('FQX07','Data/Core/Defs/ThingDefs_Items/Items_Exotic.xml','/Defs/ThingDef[@Name="ResourceVerbBase"]'),
 @('FQX08','Data/Core/Defs/ThingDefs_Items/Items_Resource_Base.xml','/Defs/ThingDef[@Name="ResourceBase"]')
)
$claims[10].sources+=@((Source '.local-research/energy/Verse.ThingDef.cs' 460 471),(Source '.local-research/storyteller/RimWorld.StatWorker_MarketValue.cs' 99 120))
$claims[10].xml+=@('FQX06')
$keep=@('defName','thingClass','statBases','comps','costStuffCount','size','surfaceType','stuffProps','workerClass','defaultBaseValue','minValue','maxValue','roundValue','roundToFiveOver','valueIfMissing','parts','volumePerUnit','smallVolume')
$xml=@(foreach($spec in $specs){
 $path=Join-Path $GameRoot $spec[1];$doc=[xml](Get-Content $path -Raw);$nodes=$doc.SelectNodes($spec[2]);if(!$nodes.Count){throw "Empty $($spec[0])"}
 $selected=@(foreach($node in $nodes){$copy=$node.CloneNode($false);foreach($child in $node.ChildNodes){if($child.LocalName -in $keep){[void]$copy.AppendChild($child.CloneNode($true))}};$copy.OuterXml})
 [ordered]@{id=$spec[0];file=$spec[1];source_sha256=(Get-FileHash $path).Hash.ToLowerInvariant();xpath=$spec[2];projection='Original attributes and selected gameplay children; full ancestry retained for four furniture and wood';nodes=$selected}
})
$manifest=Get-Content (Join-Path $out 'furniture-quality-manifest.json') -Raw|ConvertFrom-Json
$prior=Get-Content (Join-Path $out 'social-interaction-evidence.json') -Raw|ConvertFrom-Json
$e=[ordered]@{evidence_id='RW17-FURNITURE-QUALITY-MECHANISMS';date_local='2026-11-04';version_text=$manifest.version_text;source_sha256=$manifest.source_sha256;kind='Static derived C# and shipped Core XML, ordinary native case separately documented';manifests=@('furniture-quality','weapons','armor','skills','housing','storyteller','anatomy','economy','environment','energy');claims=$claims;xml=$xml;rea_members=$prior.rea_members;limitations=@('Derived C# is not original source; existing exact-version derivations reused.','REA67108864byte member-budget failure retained; not retried.','Core XML selection is not a fully patched Def database.','One Poor bed observation does not establish the distribution or execute every branch.')}
[IO.File]::WriteAllText((Join-Path $out 'furniture-quality-evidence.json'),($e|ConvertTo-Json -Depth 20).Replace("`r`n","`n")+"`n",[Text.UTF8Encoding]::new($false))
"$($claims.Count) claims; $($xml.Count) XML selections."
